#define _GNU_SOURCE
#include <dlfcn.h>
#include <errno.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

typedef ssize_t (*readlink_fn)(const char *, char *, size_t);
typedef char *(*realpath_fn)(const char *, char *);

ssize_t readlink(const char *path, char *buf, size_t size) {
  static readlink_fn next = NULL;
  if (next == NULL) next = (readlink_fn)dlsym(RTLD_NEXT, "readlink");
  ssize_t result = next(path, buf, size);
  int saved = errno;
  fprintf(stderr, "TRACE readlink(%s) = %zd errno=%d", path, result, saved);
  if (result >= 0) fprintf(stderr, " value=%.*s", (int)result, buf);
  fputc('\n', stderr);
  errno = saved;
  return result;
}

char *realpath(const char *path, char *resolved) {
  static realpath_fn next = NULL;
  if (next == NULL) next = (realpath_fn)dlsym(RTLD_NEXT, "realpath");
  char *result = next(path, resolved);
  int saved = errno;
  fprintf(stderr, "TRACE realpath(%s) = %s errno=%d\n",
          path, result == NULL ? "(null)" : result, saved);
  errno = saved;
  return result;
}

